  function countdown(el2, deadline, serverNow, opts = {}) {
    if (!el2) return;
    const target = deadline ? new Date(deadline).getTime() : NaN;
    if (!deadline || Number.isNaN(target)) {
      el2.textContent = "";
      return;
    }
    const skew = serverNow ? new Date(serverNow).getTime() - Date.now() : 0;
    const HOUR = 36e5, DAY = 864e5;
    let timer = null;
    function fmt(ms) {
      if (ms <= 0) return "0 s";
      let s = Math.round(ms / 1e3);
      const d = Math.floor(s / 86400);
      s -= d * 86400;
      const h = Math.floor(s / 3600);
      s -= h * 3600;
      const m = Math.floor(s / 60);
      s -= m * 60;
      if (d >= 2) return d + " days";
      if (d === 1) return "1 d " + h + " h " + m + " m";
      if (h > 0) return h + " h " + m + " m";
      if (m > 0) return m + " m " + String(s).padStart(2, "0") + " s";
      return s + " s";
    }
    function tick() {
      if (!el2.isConnected) {
        if (timer) clearTimeout(timer);
        return;
      }
      const ms = target - (Date.now() + skew);
      const slot = el2.querySelector(".v") || el2;
      slot.textContent = fmt(ms);
      const urgent = !opts.quiet && ms > 0 && ms <= HOUR;
      const soon = !opts.quiet && ms > 0 && !urgent && ms <= DAY;
      el2.classList.toggle("urgent", urgent);
      el2.classList.toggle("soon", soon);
      if (ms <= 0) {
        if (timer) clearTimeout(timer);
        return;
      }
      timer = setTimeout(tick, ms <= HOUR ? 1e3 : 6e4);
    }
    tick();
  }
